import { createHash } from 'node:crypto';
import { performance } from 'node:perf_hooks';
import type { DemoEvent, ScenarioName } from '@gridrisk/shared';
import { SHELTERS, ZONES } from '@gridrisk/shared/fixtures';
import { analyze } from './analyze';
import { buildScenario, SCENARIO_NAMES, STORM_NOISE_EVENTS } from './scenarios';

/** A labeled benchmark case; labels are not generated by the engine. */
export interface EvaluationCase {
  id: string;
  scenario: EvaluationScenarioName;
  split: 'development' | 'holdout';
  expectedIsolatedZoneIds: string[];
  labelSource: 'synthetic-scenario-spec';
}

export type EvaluationScenarioName =
  ScenarioName | 'holdout-zone-b' | 'holdout-multi-zone' | 'holdout-storm';

/** Increment whenever cases or labels change. */
export const EVALUATION_VERSION = '2026-11-01.v2';
export const LATENCY_WARMUP_RUNS = 5;
export const LATENCY_MEASURED_RUNS = 25;

export const EVALUATION_CASES: readonly EvaluationCase[] = [
  {
    id: 'case-calm',
    scenario: 'calm',
    split: 'development',
    expectedIsolatedZoneIds: [],
    labelSource: 'synthetic-scenario-spec',
  },
  {
    id: 'case-partial',
    scenario: 'partial',
    split: 'development',
    expectedIsolatedZoneIds: [],
    labelSource: 'synthetic-scenario-spec',
  },
  {
    id: 'case-escalation',
    scenario: 'escalation',
    split: 'development',
    expectedIsolatedZoneIds: ['zone-a'],
    labelSource: 'synthetic-scenario-spec',
  },
  {
    id: 'case-reopened',
    scenario: 'reopened',
    split: 'development',
    expectedIsolatedZoneIds: [],
    labelSource: 'synthetic-scenario-spec',
  },
  {
    id: 'case-zone-b',
    scenario: 'holdout-zone-b',
    split: 'holdout',
    expectedIsolatedZoneIds: ['zone-b'],
    labelSource: 'synthetic-scenario-spec',
  },
  {
    id: 'case-multi-zone',
    scenario: 'holdout-multi-zone',
    split: 'holdout',
    expectedIsolatedZoneIds: ['zone-a', 'zone-b'],
    labelSource: 'synthetic-scenario-spec',
  },
  {
    id: 'case-storm',
    scenario: 'holdout-storm',
    split: 'holdout',
    expectedIsolatedZoneIds: ['zone-a'],
    labelSource: 'synthetic-scenario-spec',
  },
];

export interface ProportionInterval {
  estimate: number;
  lower95: number;
  upper95: number;
}

export interface ClassificationMetrics {
  evaluatedZones: number;
  truePositives: number;
  trueNegatives: number;
  falsePositives: number;
  falseNegatives: number;
  accuracy: number;
  precision: number;
  recall: number;
  specificity: number;
  f1: number;
  balancedAccuracy: number;
  matthewsCorrelation: number;
  falseAlertRate: number;
  missedAlertRate: number;
  precision95: ProportionInterval;
  recall95: ProportionInterval;
  falseAlertRate95: ProportionInterval;
}

export interface EvaluationCaseResult {
  id: string;
  scenario: EvaluationScenarioName;
  split: EvaluationCase['split'];
  expectedIsolatedZoneIds: string[];
  predictedIsolatedZoneIds: string[];
  correct: boolean;
  latencyMs: { median: number; p95: number };
}

export interface EvaluationReport {
  generatedAt: string;
  benchmark: {
    name: string;
    version: string;
    labelSource: 'synthetic-scenario-spec';
    cases: number;
    zonesPerCase: number;
    developmentCases: number;
    holdoutCases: number;
    manifestSha256: string;
    fieldAccuracyAvailable: false;
  };
  development: ClassificationMetrics;
  holdout: ClassificationMetrics;
  overall: ClassificationMetrics;
  latencyMs: { min: number; median: number; p95: number; p99: number; max: number };
  robustness: {
    checks: number;
    passed: number;
    eventOrderInvariant: number;
    irrelevantNoiseInvariant: number;
  };
  runtime: { node: string; platform: string; warmupRuns: number; measuredRuns: number };
  cases: EvaluationCaseResult[];
}

const rate = (numerator: number, denominator: number): number =>
  denominator === 0 ? 0 : numerator / denominator;

function percentile(values: number[], p: number): number {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const index = Math.min(sorted.length - 1, Math.ceil((sorted.length - 1) * p));
  return Number((sorted[index] ?? 0).toFixed(3));
}

/** Wilson score interval; avoids overstating certainty on tiny samples. */
function wilson(successes: number, trials: number): ProportionInterval {
  if (trials === 0) return { estimate: 0, lower95: 0, upper95: 0 };
  const z = 1.96;
  const estimate = successes / trials;
  const denominator = 1 + (z * z) / trials;
  const center = (estimate + (z * z) / (2 * trials)) / denominator;
  const margin =
    (z / denominator) *
    Math.sqrt((estimate * (1 - estimate)) / trials + (z * z) / (4 * trials * trials));
  return {
    estimate,
    lower95: Math.max(0, center - margin),
    upper95: Math.min(1, center + margin),
  };
}

function classification(
  cases: readonly EvaluationCase[],
  predictions: ReadonlyMap<string, string[]>,
): ClassificationMetrics {
  let truePositives = 0;
  let trueNegatives = 0;
  let falsePositives = 0;
  let falseNegatives = 0;
  for (const evaluationCase of cases) {
    const expected = new Set(evaluationCase.expectedIsolatedZoneIds);
    const predicted = new Set(predictions.get(evaluationCase.id) ?? []);
    for (const zone of ZONES) {
      const actual = expected.has(zone.id);
      const detected = predicted.has(zone.id);
      if (actual && detected) truePositives += 1;
      else if (!actual && !detected) trueNegatives += 1;
      else if (!actual && detected) falsePositives += 1;
      else falseNegatives += 1;
    }
  }
  const total = truePositives + trueNegatives + falsePositives + falseNegatives;
  const precision = rate(truePositives, truePositives + falsePositives);
  const recall = rate(truePositives, truePositives + falseNegatives);
  const specificity = rate(trueNegatives, trueNegatives + falsePositives);
  const f1 = rate(2 * precision * recall, precision + recall);
  const denominator = Math.sqrt(
    (truePositives + falsePositives) *
      (truePositives + falseNegatives) *
      (trueNegatives + falsePositives) *
      (trueNegatives + falseNegatives),
  );
  return {
    evaluatedZones: total,
    truePositives,
    trueNegatives,
    falsePositives,
    falseNegatives,
    accuracy: rate(truePositives + trueNegatives, total),
    precision,
    recall,
    specificity,
    f1,
    balancedAccuracy: (recall + specificity) / 2,
    matthewsCorrelation:
      denominator === 0
        ? 0
        : (truePositives * trueNegatives - falsePositives * falseNegatives) / denominator,
    falseAlertRate: rate(falsePositives, trueNegatives + falsePositives),
    missedAlertRate: rate(falseNegatives, truePositives + falseNegatives),
    precision95: wilson(truePositives, truePositives + falsePositives),
    recall95: wilson(truePositives, truePositives + falseNegatives),
    falseAlertRate95: wilson(falsePositives, trueNegatives + falsePositives),
  };
}

function scenarioEvents(name: EvaluationScenarioName): DemoEvent[] {
  if (name === 'holdout-zone-b') return buildScenario('zone-b');
  if (name === 'holdout-multi-zone') return buildScenario('multi-zone');
  if (name === 'holdout-storm') return buildScenario('storm');
  return buildScenario(name);
}

function predict(events: DemoEvent[]): string[] {
  return analyze(events, ZONES, { shelters: SHELTERS })
    .filter((result) => result.isolated)
    .map((result) => result.zoneId)
    .sort();
}

function latencyFor(events: DemoEvent[]): number[] {
  for (let i = 0; i < LATENCY_WARMUP_RUNS; i += 1) predict(events);
  const samples: number[] = [];
  for (let i = 0; i < LATENCY_MEASURED_RUNS; i += 1) {
    const started = performance.now();
    predict(events);
    samples.push(performance.now() - started);
  }
  return samples;
}

function manifestHash(cases: readonly EvaluationCase[]): string {
  return createHash('sha256').update(JSON.stringify(cases)).digest('hex');
}

export function runEvaluation(
  cases: readonly EvaluationCase[] = EVALUATION_CASES,
): EvaluationReport {
  const predictions = new Map<string, string[]>();
  const allLatency: number[] = [];
  const results = cases.map((evaluationCase): EvaluationCaseResult => {
    const events = scenarioEvents(evaluationCase.scenario);
    const predicted = predict(events);
    predictions.set(evaluationCase.id, predicted);
    const samples = latencyFor(events);
    allLatency.push(...samples);
    const expected = [...evaluationCase.expectedIsolatedZoneIds].sort();
    return {
      id: evaluationCase.id,
      scenario: evaluationCase.scenario,
      split: evaluationCase.split,
      expectedIsolatedZoneIds: expected,
      predictedIsolatedZoneIds: predicted,
      correct: JSON.stringify(expected) === JSON.stringify(predicted),
      latencyMs: { median: percentile(samples, 0.5), p95: percentile(samples, 0.95) },
    };
  });

  let robustnessPassed = 0;
  let eventOrderInvariant = 0;
  let irrelevantNoiseInvariant = 0;
  for (const evaluationCase of cases) {
    const base = predictions.get(evaluationCase.id) ?? [];
    const events = scenarioEvents(evaluationCase.scenario);
    if (JSON.stringify(base) === JSON.stringify(predict([...events].reverse()))) {
      eventOrderInvariant += 1;
      robustnessPassed += 1;
    }
    const noisy = predict([
      ...events,
      ...STORM_NOISE_EVENTS.filter((event) => !events.some((item) => item.id === event.id)),
    ]);
    if (JSON.stringify(base) === JSON.stringify(noisy)) {
      irrelevantNoiseInvariant += 1;
      robustnessPassed += 1;
    }
  }
  const development = cases.filter((evaluationCase) => evaluationCase.split === 'development');
  const holdout = cases.filter((evaluationCase) => evaluationCase.split === 'holdout');
  return {
    generatedAt: new Date().toISOString(),
    benchmark: {
      name: 'GridRisk synthetic isolation benchmark',
      version: EVALUATION_VERSION,
      labelSource: 'synthetic-scenario-spec',
      cases: cases.length,
      zonesPerCase: ZONES.length,
      developmentCases: development.length,
      holdoutCases: holdout.length,
      manifestSha256: manifestHash(cases),
      fieldAccuracyAvailable: false,
    },
    development: classification(development, predictions),
    holdout: classification(holdout, predictions),
    overall: classification(cases, predictions),
    latencyMs: {
      min: allLatency.length ? Number(Math.min(...allLatency).toFixed(3)) : 0,
      median: percentile(allLatency, 0.5),
      p95: percentile(allLatency, 0.95),
      p99: percentile(allLatency, 0.99),
      max: allLatency.length ? Number(Math.max(...allLatency).toFixed(3)) : 0,
    },
    robustness: {
      checks: cases.length * 2,
      passed: robustnessPassed,
      eventOrderInvariant,
      irrelevantNoiseInvariant,
    },
    runtime: {
      node: process.version,
      platform: `${process.platform}-${process.arch}`,
      warmupRuns: LATENCY_WARMUP_RUNS,
      measuredRuns: LATENCY_MEASURED_RUNS,
    },
    cases: results,
  };
}

export function assertEvaluationCasesAreComplete(): void {
  const expected = new Set<string>(SCENARIO_NAMES);
  const actualNames = new Set(
    EVALUATION_CASES.map((evaluationCase) =>
      evaluationCase.scenario.startsWith('holdout-')
        ? evaluationCase.scenario.replace('holdout-', '')
        : evaluationCase.scenario,
    ),
  );
  if (expected.size !== actualNames.size || [...expected].some((name) => !actualNames.has(name))) {
    throw new Error('Evaluation cases must cover every built-in scenario');
  }
}
